// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/negotiations/:id/landlord-decision", "require_user": true, "idempotent": true, "required_consents": ["terms", "privacy", "cloud_llm_processing"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// Integer minor units only. The database repeats all authorization and amount checks.
const minor = (v) => Number.isSafeInteger(v) && v > 0 && v <= 1000000000;
const uuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
function proposal(raw, context) {
  let parsed;
  try { parsed = JSON.parse(raw); } catch { parsed = null; }
  const ceiling = Math.min(context.asking_minor, context.max_minor,
    context.counter_minor || Number.MAX_SAFE_INTEGER);
  const amount = parsed && parsed.offer_minor;
  const modelUsed = minor(amount) && amount <= ceiling;
  const fallback = Math.max(1, Math.min(context.target_minor, ceiling));
  return { amount_minor: modelUsed ? amount : fallback, model_used: !!modelUsed,
    rationale: modelUsed && typeof parsed.reasoning_summary === 'string'
      ? parsed.reasoning_summary.replace(/[\u0000-\u001f<>]/g, ' ').slice(0, 220)
      : 'Proposition prudente sous le plafond autorisé.' };
}
if (typeof module !== 'undefined') module.exports = { minor, uuid, proposal };

const gw = $input.first().json;
const b = gw.ctx.body || {};
const role = 'landlord';
const actions = role === 'renter' ? ['approve','reject'] : ['accept','reject','counter'];
const valid = uuid(gw.ctx.params.id) && Number.isSafeInteger(b.version) && b.version >= 1
  && actions.includes(b.action) && minor(b.offer_minor)
  && Object.keys(b).every(k => ['version','action','offer_minor','currency','round'].includes(k))
  && typeof b.currency === 'string' && /^[A-Z]{3}$/.test(b.currency)
  && (b.round === 1 || b.round === 2);
if (!valid) return [{json:{ok:false,gw,status:422,error:{code:'VALIDATION_FAILED',message:'Decision must identify offer, round, currency and version',details:[]}}}];
return [{json:{ok:true,gw,body:b,role,params:[gw.ctx.user_id,gw.ctx.params.id,b.version,b.action,b.offer_minor,
  JSON.stringify({submitted_round:b.round,submitted_currency:b.currency,
    request_id:gw.request_id,idempotency_key:gw.idempotency?.key||null})]}}];

const v = $('Validate decision').first().json;
const r = $input.first().json.r || {};
if (!r.ok) return [{json:{ok:false,gw:v.gw,status:r.reason==='not_found'?404:409,
  error:{code:r.reason==='not_found'?'NOT_FOUND':'CONFLICT',message:r.reason||'Decision rejected',details:[]}}}];
return [{json:{ok:true,gw:v.gw,data:r}}];

const v = $('Validate decision').first().json;
const r = $input.first().json.r || {};
if (!r.ok) return [{json:{ok:false,gw:v.gw,status:r.reason==='not_found'?404:409,
  error:{code:'CONFLICT',message:r.reason||'Decision rejected',details:[]}}}];
return [{json:{ok:true,gw:v.gw,record:r,prompt:JSON.stringify({asking_minor:Number(r.asking_minor),
 target_minor:Number(r.target_minor),max_minor:Number(r.max_minor),counter_minor:Number(r.counter_minor),
 currency:r.currency,round:2})}}];

// Integer minor units only. The database repeats all authorization and amount checks.
const minor = (v) => Number.isSafeInteger(v) && v > 0 && v <= 1000000000;
const uuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
function proposal(raw, context) {
  let parsed;
  try { parsed = JSON.parse(raw); } catch { parsed = null; }
  const ceiling = Math.min(context.asking_minor, context.max_minor,
    context.counter_minor || Number.MAX_SAFE_INTEGER);
  const amount = parsed && parsed.offer_minor;
  const modelUsed = minor(amount) && amount <= ceiling;
  const fallback = Math.max(1, Math.min(context.target_minor, ceiling));
  return { amount_minor: modelUsed ? amount : fallback, model_used: !!modelUsed,
    rationale: modelUsed && typeof parsed.reasoning_summary === 'string'
      ? parsed.reasoning_summary.replace(/[\u0000-\u001f<>]/g, ' ').slice(0, 220)
      : 'Proposition prudente sous le plafond autorisé.' };
}
if (typeof module !== 'undefined') module.exports = { minor, uuid, proposal };

const v = $('Round 2 input').first().json;
const r = v.record;
const output = $input.first().json || {};
const p = proposal(typeof output.output==='string'?output.output:'',{
  asking_minor:Number(r.asking_minor),target_minor:Number(r.target_minor),max_minor:Number(r.max_minor),
  counter_minor:Number(r.counter_minor)});
return [{json:{ok:true,gw:v.gw,record:r,proposal:p,
 params:[null,r.id,r.version,'propose',p.amount_minor,JSON.stringify({model_used:p.model_used,rationale:p.rationale,
   request_id:v.gw.request_id,idempotency_key:v.gw.idempotency?.key||null})]}}];

const v = $('Guard round 2').first().json;
const r = $input.first().json.r || {};
if (!r.ok) return [{json:{ok:false,gw:v.gw,status:409,error:{code:'CONFLICT',message:r.reason||'Proposal failed',details:[]}}}];
return [{json:{ok:true,gw:v.gw,data:{...r,currency:v.record.currency,offer_minor:v.proposal.amount_minor,
 model_used:v.proposal.model_used,rationale:v.proposal.rationale,
 notice:'Round 2 draft for renter review only; no message was sent.'}}}];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
